				return invalidInputHandler(
					{ path },
					{
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					},
				);
			}
			throw new ToolInputValidationError({ path });
		}
		return handler(
			parsed,
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		);
	});
}

