  "version": "1.3.2",
  "peerDependencies": {
    "vitest": "^4.1.0",
    "@vitest/runner": "^4.1.0",
    "@vitest/snapshot": "^4.1.0"
  }
}

#!/bin/bash
command -v mise >/dev/null 2>&1 || { echo "mise not found; control-plane pre-push step skipped" >&2; exit 0; }
mise exec -- npx nx run repository:pre-push
